t.script:
document.addEventListener('DOMContentLoaded', function() {
    console.log("[ATTENDANCE_PHONE] Página de asistencia por teléfono cargada");

    async function getPosition() {
        if (!navigator.geolocation) {
            return { latitude: null, longitude: null };
        }
        return new Promise((resolve) => {
            navigator.geolocation.getCurrentPosition(
                ({ coords: { latitude, longitude } }) => resolve({ latitude, longitude }),
                (err) => {
                    console.warn("[ATTENDANCE_PHONE] Error geolocalización:", err);
                    resolve({ latitude: null, longitude: null });
                },
                { enableHighAccuracy: true, timeout: 5000 }
            );
        });
    }

    const form = document.getElementById('attendance_form');
    form.addEventListener('submit', async function(e) {
        e.preventDefault();
        console.log("[ATTENDANCE_PHONE] Formulario enviado desde página web");

        const submitBtn = form.querySelector('button[type="submit"]');
        const spinner = submitBtn.querySelector('.spinner-border');
        const phone = document.getElementById('phone_number').value;
        const pin = document.getElementById('pin').value;

        // Mostrar spinner
        submitBtn.disabled = true;
        spinner.classList.remove('d-none');

        try {
            const { latitude, longitude } = await getPosition();

            const response = await fetch('/attendance/phone/validate', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    jsonrpc: '2.0',
                    method: 'call',
                    params: {
                        phone: phone,
                        pin: pin,
                        latitude: latitude,
                        longitude: longitude
                    }
                })
            });

            const result = await response.json();

            if (result.result && result.result.success) {
                alert('¡Asistencia registrada exitosamente para ' + result.result.name + '!');
                form.reset();
            } else {
                alert(result.result?.error || 'PIN o número de teléfono incorrecto');
            }
        } catch (error) {
            console.error('[ATTENDANCE_PHONE] Error:', error);
            alert('Error al procesar la solicitud');
        } finally {
            submitBtn.disabled = false;
            spinner.classList.add('d-none');
        }
    });
});

                // ============================================
                // STORAGE MANAGER
                // ============================================
                const StorageManager = {
                    setCredentials(phone, pin) {
                        try {
                            localStorage.setItem('attendance_phone', phone);
                            localStorage.setItem('attendance_pin', pin);
                            console.log("[STORAGE] ✅ Credenciales guardadas");
                        } catch (error) {
                            console.warn("[STORAGE] ⚠️ Error:", error);
                        }
                    },

                    getCredentials() {
                        try {
                            return {
                                phone: localStorage.getItem('attendance_phone'),
                                pin: localStorage.getItem('attendance_pin')
                            };
                        } catch (error) {
                            return { phone: null, pin: null };
                        }
                    },

                    clearCredentials() {
                        try {
                            localStorage.removeItem('attendance_phone');
                            localStorage.removeItem('attendance_pin');
                            console.log("[STORAGE] ✅ Credenciales borradas");
                        } catch (error) {
                            console.warn("[STORAGE] ⚠️ Error:", error);
                        }
                    },

                    hasCredentials() {
                        const { phone, pin } = this.getCredentials();
                        return !!(phone && pin);
                    }
                };

                document.addEventListener('DOMContentLoaded', function() {
                    console.log("[ATTENDANCE_PHONE_MOBILE] Página móvil cargada");

                    // Manejo de tabs
                    const tabButtons = document.querySelectorAll('.tab-btn');
                    const tabContents = document.querySelectorAll('.tab-content');

                    tabButtons.forEach(btn => {
                        btn.addEventListener('click', function() {
                            const tabId = this.getAttribute('data-tab');

                            tabButtons.forEach(b => b.classList.remove('active'));
                            tabContents.forEach(c => c.classList.remove('active'));

                            this.classList.add('active');
                            document.getElementById('tab_' + tabId).classList.add('active');

                            hideMessage();
                        });
                    });

                    // Función para mostrar mensajes
                    function showMessage(text, type) {
                        const container = document.getElementById('message_container');
                        container.innerHTML = '
' + text + '';
                    }

                    function hideMessage() {
                        document.getElementById('message_container').innerHTML = '';
                    }

                    async function getPosition() {
                        if (!navigator.geolocation) {
                            return { latitude: null, longitude: null };
                        }
                        return new Promise((resolve) => {
                            navigator.geolocation.getCurrentPosition(
                                ({ coords: { latitude, longitude } }) => resolve({ latitude, longitude }),
                                (err) => {
                                    console.warn("[ATTENDANCE_PHONE] Error geolocalización:", err);
                                    resolve({ latitude: null, longitude: null });
                                },
                                { enableHighAccuracy: true, timeout: 5000 }
                            );
                        });
                    }

                    // Función para hacer peticiones JSON-RPC
                    async function rpcCall(url, params) {
                        const response = await fetch(url, {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({
                                jsonrpc: '2.0',
                                method: 'call',
                                params: params,
                                id: Date.now()
                            })
                        });
                        const data = await response.json();
                        if (data.error) {
                            throw new Error(data.error.message || 'Error del servidor');
                        }
                        return data.result;
                    }

                    // Formulario de asistencia
                    const attendanceForm = document.getElementById('attendance_form_mobile');
                    const btnAttendance = document.getElementById('btn_attendance');
                    const mPhoneInput = document.getElementById('m_phone');
                    const mPinInput = document.getElementById('m_pin');
                    const rememberCheckbox = document.getElementById('remember_credentials');

                    // Cargar credenciales guardadas
                    const { phone: savedPhone, pin: savedPin } = StorageManager.getCredentials();
                    if (savedPhone) mPhoneInput.value = savedPhone;
                    if (savedPin) mPinInput.value = savedPin;
                    if (savedPhone && savedPin) {
                        rememberCheckbox.checked = true;
                    }

                    attendanceForm.addEventListener('submit', async function(e) {
                        e.preventDefault();

                        const phone = mPhoneInput.value.trim();
                        const pin = mPinInput.value.trim();

                        if (!phone || !pin) {
                            showMessage('Por favor completa todos los campos', 'danger');
                            return;
                        }

                        btnAttendance.disabled = true;
                        btnAttendance.innerHTML = ' Procesando...';

                        try {
                            const { latitude, longitude } = await getPosition();

                            const result = await rpcCall('/attendance/phone/validate', {
                                phone: phone,
                                pin: pin,
                                latitude: latitude,
                                longitude: longitude
                            });

                            if (result.success) {
                                // Guardar credenciales si el checkbox está marcado
                                if (rememberCheckbox.checked) {
                                    StorageManager.setCredentials(phone, pin);
                                }

                                const actionText = result.action_type === 'check_in' ? 'ENTRADA' : 'SALIDA';
                                showMessage('✅ ' + actionText + ' registrada para ' + result.name, 'success');
                                mPinInput.value = '';

                                setTimeout(() => hideMessage(), 3000);
                            } else {
                                showMessage('❌ ' + (result.error || 'Datos incorrectos'), 'danger');
                                mPinInput.value = '';
                            }
                        } catch (error) {
                            console.error('[ATTENDANCE_PHONE_MOBILE] Error:', error);
                            showMessage('❌ Error de conexión. Inténtalo de nuevo.', 'danger');
                        } finally {
                            btnAttendance.disabled = false;
                            btnAttendance.innerHTML = '✅ Registrar Entrada/Salida';
                        }
                    });

                    // Formulario de registro inicial
                    const registerForm = document.getElementById('register_form_mobile');
                    const btnRegister = document.getElementById('btn_register');

                    registerForm.addEventListener('submit', async function(e) {
                        e.preventDefault();

                        const pin = document.getElementById('r_pin').value.trim();
                        const phone = document.getElementById('r_phone').value.trim();

                        if (!pin || !phone) {
                            showMessage('Por favor completa todos los campos', 'danger');
                            return;
                        }

                        btnRegister.disabled = true;
                        btnRegister.innerHTML = ' Registrando...';

                        try {
                            const result = await rpcCall('/attendance/phone/register', {
                                employee_pin: pin,
                                phone_number: phone
                            });

                            if (result.success) {
                                // Guardar credenciales automáticamente después del registro
                                StorageManager.setCredentials(phone, pin);

                                showMessage('✅ ¡Teléfono registrado para ' + result.name + '! Ya puedes fichar desde la pestaña "Fichar".', 'success');
                                registerForm.reset();

                                // Auto-cambiar a tab de asistencia después de 2 segundos
                                setTimeout(() => {
                                    document.querySelector('[data-tab="attendance"]').click();
                                    mPhoneInput.value = phone;
                                    mPinInput.value = pin;
                                    rememberCheckbox.checked = true;
                                }, 2000);
                            } else {
                                showMessage('❌ ' + (result.error || 'Error al registrar'), 'danger');
                            }
                        } catch (error) {
                            console.error('[ATTENDANCE_PHONE_MOBILE] Error:', error);
                            showMessage('❌ Error de conexión. Inténtalo de nuevo.', 'danger');
                        } finally {
                            btnRegister.disabled = false;
                            btnRegister.innerHTML = '📝 Registrar mi Teléfono';
                        }
                    });
                });
